public class Solution {
    public String processAccountStatus(int age, boolean isVerified, double balance, String tier, boolean hasPendingDisputes) {
        if (!isVerified || !checkAge(age)) return "ERROR_UNVERIFIED";
        if (hasPendingDisputes) return "ERROR_PENDING_DISPUTES";
        if (!checkBalance(balance)) return "ERROR_INSUFFICIENT_FUNDS";
        switch (tier.toUpperCase()) {
            case "VIP":
            case "GOLD":
                return "ACCOUNT_PREMIUM_ACTIVE";
            default:
                return "ACCOUNT_STANDARD_ACTIVE";
        }
    }

    private boolean checkAge(int age) {
        if (age < 18) throw new IllegalArgumentException("ERROR_UNDERAGE");
        return true;
    }

    private boolean checkBalance(double balance) {
        if (balance < 100.0) throw new IllegalArgumentException("ERROR_INSUFFICIENT_FUNDS");
        return true;
    }
}

